edits.before:
        self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                self.adjustDate('subtract', 1);
                break;
            case 38:
                self.adjustDate('subtract', 7);
                break;
            case 39:
                self.adjustDate('add', 1);
                break;
            case 40:
                self.adjustDate('add', 7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
}

edits.after:
        self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {

        var skipDisabled = function(sign, amount) {
            var safety = 0;
            while (safety < 100) {
                self.adjustDate(sign, amount);
                var current = self.getDate();
                if (!current) {
                    return;
                }
                if (opts.disableDayFn && opts.disableDayFn(current)) {
                    safety++;
                    continue;
                }
                return;
            }
        };

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                skipDisabled('subtract', 1);
                break;
            case 38:
                skipDisabled('subtract', 7);
                break;
            case 39:
                skipDisabled('add', 1);
                break;
            case 40:
                skipDisabled('add', 7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
}
